pe:Prolog_ControlFlow_assertion a tbox:LanguageSupportAssertion ;
    tbox:assertedForConcept ce:ControlFlow ;
    tbox:assertedForLanguage pe:Prolog ;
    tbox:hasDominantForm ce:Backtracking ;
    tbox:hasPrimaryMechanism ce:BacktrackingMechanism ;
    tbox:hasSupportKind ce:NativeSupport .

pe:Python_IteratorsAndGenerators_assertion a tbox:LanguageSupportAssertion ;
    tbox:assertedForConcept ce:IteratorsAndGenerators ;
    tbox:assertedForLanguage pe:Python ;
    tbox:hasDominantForm ce:Coroutines ;
    tbox:hasPrimaryMechanism ce:GeneratorProtocolMechanism ;
