pe:Python_Objects_assertion a tbox:LanguageSupportAssertion ;
    tbox:assertedForConcept ce:Objects ;
    tbox:assertedForLanguage pe:Python ;
    tbox:hasDominantForm ce:ObjectOrientedParadigm ;
    tbox:hasPrimaryMechanism ce:ClassBasedMechanism ;
    tbox:hasSupportKind ce:NativeSupport .

pe:Scheme_ContinuationPassingStyle_assertion a tbox:LanguageSupportAssertion ;
    tbox:assertedForConcept ce:ContinuationPassingStyle ;
